{
  "sql": "SELECT t1.product_category_name_english, t2.mala_calificacion, t2.pct_entregas_tardias, t2.pct_global FROM product_category_translation t1 JOIN ( SELECT product_category_name_english, AVG(review_score) AS mala_calificacion, SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS pct_entregas_tardias, SUM(CASE WHEN entrega_con_retraso = 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS pct_global FROM vw_ventas_pedido WHERE product_category_name_english IS NOT NULL GROUP BY product_category_name_english HAVING COUNT(*) >= 100 ) t2 ON t1.product_category_name_english = t2.product_category_name_english WHERE t2.mala_calificacion < ( SELECT AVG(review_score) FROM vw_ventas_pedido ) AND t2.pct_entregas_tardias < ( SELECT SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) FROM vw_ventas_pedido WHERE entrega_con_retraso IS NOT NULL )"
}

